import healthcare;

class VitalSigns {
    blood_pressure: int;
    heart_rate: int;
}

class LabResults {
    total_cholesterol: int;
}

class Patient {
    patient_id: string;
    age: int;
    gender: string;
    vital_signs: VitalSigns;
    lab_results: LabResults;
}

let vitals := new VitalSigns {
    blood_pressure := 130,
    heart_rate     := 78,
};

let labs := new LabResults {
    total_cholesterol := 210,
};

let patient := new Patient {
    patient_id  := "PAT001",
    age         := 50,
    gender      := "M",
    vital_signs := vitals,
    lab_results := labs,
};

let results := parallel [all] [{
    #[on("bob")]
    return analyze_heart_disease(patient);
}, {
    #[on("alice")]
    return analyze_heart_disease(patient);
}];

println(results[0]);
println(results[1]);

